function canBuild(note, magazine) {
  const have = new Map();
  for (const c of magazine) have.set(c, (have.get(c) ?? 0) + 1);
  for (const c of note) {
    const n = have.get(c) ?? 0;
    if (n === 0) return false;
    have.set(c, n - 1);
  }
  return true;
}
console.log(canBuild('aab', 'baa'), canBuild('aa', 'ab'), canBuild('', 'x'));

