function longest(s) {
  const last = new Map();
  let left = 0, best = 0;
  for (let r = 0; r < s.length; r++) {
    if (last.has(s[r])) left = Math.max(left, last.get(s[r]) + 1);
    last.set(s[r], r);
    best = Math.max(best, r - left + 1);
  }
  return best;
}
console.log(longest('abcabcbb'), longest('pwwkew'), longest('abba'));

