function perms(s) {
  if (s.length <= 1) return [s];
  const out = [];
  for (let i = 0; i < s.length; i++) {
    const rest = s.slice(0, i) + s.slice(i + 1);
    for (const p of perms(rest)) out.push(s[i] + p);
  }
  return out;
}
const res = perms('abc');
